%% Union of every admitted message type. Records are the tagged tuples
%% defined (and constructed) by beam4pm_mcp_contracts; this module never
%% touches the -record declarations directly -- it dispatches on element(1)
%% and reads fields positionally, and it builds records only through the
%% validating beam4pm_mcp_contracts:new_*/1 constructors.
-type known_record() ::
    beam4pm_mcp_contracts:mcp_resource() |
    beam4pm_mcp_contracts:mcp_resource_read_request() |
    beam4pm_mcp_contracts:mcp_resource_read_result() |
    beam4pm_mcp_contracts:mcp_tool() |
