-spec to_map(known_record()) -> #{binary() => term()}.
to_map(R) when element(1, R) =:= mcp_resource ->
    pairs_to_map([
        {<<"uri">>, plain, element(2, R)},
        {<<"name">>, plain, element(3, R)},
        {<<"title">>, plain, element(4, R)},
        {<<"description">>, plain, element(5, R)},
        {<<"mimeType">>, plain, element(6, R)},
        {<<"size">>, plain, element(7, R)}
