    beam4pm_mcp_contracts:new_mcp_resource(take_known(Map, [
        {<<"uri">>, uri, plain},
        {<<"name">>, name, plain},
        {<<"title">>, title, plain},
        {<<"description">>, description, plain},
        {<<"mimeType">>, mime_type, plain},
        {<<"size">>, size, plain}
    ]));
from_map(mcp_resource_read_request, Map) when is_map(Map) ->
    beam4pm_mcp_contracts:new_mcp_resource_read_request(take_known(Map, [
        {<<"uri">>, uri, plain}
